const chips=ids=>`<div class="term-chips">${ids.filter(id=>termById(id)).map(id=>`<button type="button" data-term="${e(id)}">${e(termById(id).term)} ↗</button>`).join('')}</div>`;
const mark=text=>termMarkup(text,terms);
const pill=(text)=>`<span class="class-tag">${e(text)}</span>`;
function persist(){const ok=storage.save(state);$('#storage-warning').hidden=ok;return ok;}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2500);}
function applySettings(){document.documentElement.dataset.sidebar=state.sidebarCollapsed?'collapsed':'expanded';$('#menu-toggle').setAttribute('aria-expanded',String(!state.sidebarCollapsed));document.documentElement.dataset.theme=state.theme;document.documentElement.dataset.font=state.fontSize;$('#theme').value=state.theme;$('#text-size').setAttribute('aria-pressed',state.fontSize==='large');$('#text-size').setAttribute('aria-label',state.fontSize==='large'?'Use normal lesson text':'Use larger lesson text');}
function navMarkup(){const v=current?.view;const cls=lessonById(current?.id)?.classId||objectiveById(current?.id)?.classId;return `<a class="nav-item ${v==='home'?'active':''}" href="#/home" ${v==='home'?'aria-current="page"':''}><span aria-hidden="true">⌂</span>Learning overview</a><div class="nav-section">YOUR CLASSES</div>${course.classes.map((c,i)=>`<details class="class-navigation" ${cls===c.id?'open':''}><summary><span>${String(i+1).padStart(2,'0')}</span>Class ${i+1}<span class="class-chevron" aria-hidden="true">⌄</span></summary><div class="class-objectives">${course.objectives.filter(o=>o.classId===c.id).map(o=>{const active=(v==='objective'&&current.id===o.id)||(v==='lesson'&&lessonById(current.id)?.objectiveId===o.id);return `<a class="nav-item objective-side ${active?'active':''}" href="#/objective/${o.id}" ${active?'aria-current="page"':''}><span>${o.number}</span>${e(o.title)}</a>`;}).join('')}</div></details>`).join('')}<div class="nav-section">LEARNING TOOLS</div><a class="nav-item ${v==='glossary'?'active':''}" href="#/glossary"><span aria-hidden="true">▤</span>Simple glossary <span class="nav-count">${terms.length}</span></a><a class="nav-item ${v==='practice'?'active':''}" href="#/practice/all"><span aria-hidden="true">✓</span>Thought questions <span class="nav-count">10</span></a><a class="nav-item ${v==='slides'?'active':''}" href="#/slides/class1/1"><span aria-hidden="true">▧</span>Original slides <span class="nav-count">30</span></a><a class="nav-item ${v==='notes'?'active':''}" href="#/notes"><span aria-hidden="true">✎</span>My notes & bookmarks</a><div class="nav-section">HELP & ABOUT</div><a class="nav-item ${v==='guide'?'active':''}" href="#/guide"><span aria-hidden="true">?</span>User Guide</a><a class="nav-item ${v==='developer'?'active':''}" href="#/developer"><span aria-hidden="true">ⓘ</span>About the Developer</a><a class="nav-item ${v==='about'?'active':''}" href="#/about"><span aria-hidden="true">▧</span>Course & sources</a>`;}
function updateShell(){const nav=navMarkup();$('#desktop-nav').innerHTML=nav;$('#mobile-nav').innerHTML=nav;const p=progress(course,state);$('#side-progress').innerHTML=`<progress value="${p.done}" max="${p.total}" aria-label="Lessons marked complete"></progress><div class="progress-caption"><span>${p.done} of ${p.total} lessons</span><span>${p.percent}%</span></div>`;$('#global-back').disabled=!current||current.view==='home';$('#storage-warning').hidden=storage.persistent;}
function capture(){if(!current)return null;const key=routeKey(current);const context=makeContext(current,window.scrollY,document.activeElement?.id||'',[...main.querySelectorAll('details[open][id]')].map(x=>x.id));state.contexts[key]=context;if(current.view==='lesson')state.lastLesson=context;persist();return context;}
function restore(context,{focus=true}={}){if(!context)return;requestAnimationFrame(()=>{for(const id of context.openDetails||[]){const node=document.getElementById(id);if(node instanceof HTMLDetailsElement)node.open=true;}if(focus&&context.focusId)document.getElementById(context.focusId)?.focus({preventScroll:true});window.scrollTo({top:context.scrollY||0,behavior:'auto'});});}
function navigate(route,{restoreContext=null,replace=false}={}){capture();const mobile=$('#mobile-menu');if(mobile.open){mobile.close();updateMenuButton();}if(dialog.open)dialog.close();previousFigure=null;overlayHasHistory=false;history[replace?'replaceState':'pushState']({route:true},'',routeHash(route));syncRoute(restoreContext);}
function goBack(){if(dialog.open){closeOverlay();return;}if(history.state?.route||history.state?.overlay){capture();history.back();}else if(current.view==='lesson'){navigate({view:'objective',id:lessonById(current.id)?.objectiveId||'o1'});}else navigate({view:'home'});}
function syncRoute(explicitContext=null){const next=parseRoute(location.hash);const same=current&&routeKey(next)===routeKey(current);
 if(!same){if(current)capture();current={...next,overlay:''};main.innerHTML=renderView(current);decorate();updateShell();document.title=(main.querySelector('h1')?.textContent||course.title)+' · Meiosis Learning Hub';const context=explicitContext||state.contexts[routeKey(current)];if(context)restore(context);else{window.scrollTo({top:0,behavior:'auto'});main.focus({preventScroll:true});}}
 if(next.overlay){const [kind,id]=next.overlay.split(':');renderOverlay(kind,id);}else if(dialog.open){dialog.close();restore(overlayContext);overlayContext=null;overlayHasHistory=false;previousFigure=null;}
}
function openOverlay(kind,id){if(!dialog.open)termTrail=[];else if(kind==='term'){const active=parseRoute(location.hash).overlay;if(active?.startsWith('term:')&&active!=='term:'+id)termTrail.push(active.slice(5));}if(!dialog.open){overlayContext=capture();overlayHasHistory=true;previousFigure=null;history.pushState({overlay:true},'',routeHash({...current,overlay:kind+':'+id}));}else{history.replaceState({overlay:true},'',routeHash({...current,overlay:kind+':'+id}));}renderOverlay(kind,id);}
function closeOverlay(){if(document.fullscreenElement===dialog)document.exitFullscreen?.().catch(()=>{});if(overlayHasHistory){history.back();}else{history.replaceState(history.state,'',routeHash(current));dialog.close();restore(overlayContext);overlayContext=null;}previousFigure=null;}
function termRelevance(t){const lesson=current?.view==='lesson'?lessonById(current.id):null;const connected=l=>l.figure.terms.includes(t.id)||[t.term,...t.aliases].some(a=>[l.title,...l.body].join(' ').toLowerCase().includes(a.toLowerCase()));const match=lesson&&connected(lesson)?lesson:course.lessons.find(connected);return match?`<div class="explain-section"><h3>${match===lesson?'WHY IT MATTERS HERE':'WHERE IT FITS'}</h3><p>${e(objectiveById(match.objectiveId).goal)}</p><p class="source-note">${e(match.title)} · ${e(objectiveById(match.objectiveId).classLabel)}, slide ${match.sourceNumber}</p></div>`:'<p class="source-note">This term supports the course glossary and original thought questions.</p>';}
function renderOverlay(kind,id){const body=$('#explain-body');let html='';
 if(kind==='term'){const t=termById(id);if(!t){html=`<h2 id="explain-title">Term unavailable</h2><p>This term could not be found. Return to the lesson and try another term.</p>`;}else{html=`<div class="explain-eyebrow">The simple explanation</div><h2 id="explain-title">${e(t.term)}</h2><div class="small-label">PLAIN MEANING</div><div class="definition">${e(t.simple)}</div>${termRelevance(t)}${termTrail.length?'<button class="text-link" data-previous-term>← Previous term</button>':''}${previousFigure?`<button class="text-link" data-return-figure="${e(previousFigure)}">← Back to diagram</button>`:''}<details class="source-details"><summary>Why does it work this way?</summary><p>${e(t.how)}</p></details>${t.whyName?`<details class="source-details"><summary>Why this name?</summary><p>${e(t.whyName)}</p></details>`:''}<details class="source-details"><summary>Remember it this way</summary><p>${e(t.memory)}</p></details><details class="source-details"><summary>Related terms</summary>${chips(t.related)}</details><details class="source-details"><summary>Where it connects to the lessons</summary>${course.lessons.filter(l=>l.figure.terms.includes(id)||[l.title,...l.body].join(' ').toLowerCase().includes(t.term.toLowerCase())).map(l=>`<p><a href="#/lesson/${l.id}">${e(l.title)}</a></p>`).join('')||'<p>This term supports the original thought questions or diagram labels.</p>'}<p class="source-note">Brief glossary notes supplement the PowerPoints. <a href="https://www.genome.gov/genetics-glossary" target="_blank" rel="noopener noreferrer">NHGRI genetics glossary ↗</a></p></details>`;}}
 else if(kind==='figure'){const l=lessonById(id);if(!l){html='<h2 id="explain-title">Diagram unavailable</h2>';}else{previousFigure=l.id;const xs=[20,50,80];html=`<div class="explain-eyebrow">Explore the diagram · Class ${l.classId==='class1'?1:2}, slide ${l.sourceNumber}</div><h2 id="explain-title">${e(l.title)}</h2><div class="diagram-canvas"><img src="${e(l.figure.src)}" alt="${e(l.figure.alt)}">${l.figure.terms.map((t,i)=>`<button class="hotspot" style="left:${xs[i]}%;top:88%" data-term="${e(t)}" aria-label="Explain ${e(termById(t).term)}">${i+1}</button>`).join('')}</div><div class="explain-section"><h3>WHAT IT MEANS</h3><p>${e(l.figure.description)}</p></div>${l.figure.parts.map((p,i)=>`<div class="diagram-part"><span>${i+1}</span><p>${mark(p)}</p></div>`).join('')}<div class="explain-section"><h3>EXPLORE THE LABELS</h3>${chips(l.figure.terms)}</div><div class="explain-section"><h3>CONNECT IT TO THE OBJECTIVE</h3><p>${e(objectiveById(l.objectiveId).goal)}</p></div><div class="caution"><strong>Read the symbols carefully.</strong> ${e(l.figure.caution)}</div>`;}}
 else if(kind==='guide'){html=`<h2 id="explain-title">A simple way to learn</h2><ol><li>Choose an objective and open its lesson.</li><li>Read the explanation, then explore the original diagram.</li><li>Tap an underlined term, or select text and choose Look up selected text.</li><li>Use Back to Lesson to return to your reading position.</li><li>Try the original questions and mark the lesson complete.</li></ol><p>Quick revision shows the key idea first. Full lesson restores the teaching text. All original content remains available.</p><p>Notes and progress stay in this browser. Export a backup from My notes before changing devices.</p>`;}
 else if(kind==='slide'){const slide=sourceById(id);if(!slide){html='<h2 id="explain-title">Slide unavailable</h2>';}else{const deck=decks.find(d=>d.slides.some(s=>s.id===id)),index=deck.slides.indexOf(slide);previewZoom=100;html=`<div class="explain-eyebrow">${e(deck.title)} · SLIDE ${index+1} OF ${deck.slides.length}</div><h2 id="explain-title">${e(slide.title)}</h2><div class="document-preview-tools" aria-label="Document preview controls"><button class="button small" data-preview-zoom="out" aria-label="Zoom out">−</button><output id="preview-zoom-status" aria-live="polite">100%</output><button class="button small" data-preview-zoom="in" aria-label="Zoom in">+</button><button class="button small" data-preview-zoom="fit">Fit width</button><button class="button small" data-preview-fullscreen>Full screen</button><a class="button small" href="${e(deck.download)}" download>Download PowerPoint ↓</a></div><div class="document-preview-viewport" id="document-preview-viewport" tabindex="0" aria-label="Scrollable slide preview"><img id="preview-page" src="${e(slide.preview)}" alt="Full original slide ${slide.number}: ${e(slide.title)}"></div><div class="document-preview-nav">${index>0?`<button class="button" data-slide="${deck.slides[index-1].id}">← Previous slide</button>`:'<span></span>'}${index<deck.slides.length-1?`<button class="button" data-slide="${deck.slides[index+1].id}">Next slide →</button>`:'<span></span>'}</div><details class="source-details"><summary>Read original slide text</summary><div class="source-text">${e(slide.text.join('\n\n'))}</div></details>`;}}

 else html='<h2 id="explain-title">Explanation unavailable</h2><p>Return to your lesson to continue.</p>';
 dialog.classList[kind==='slide'?'add':'remove']('document-preview');body.innerHTML=html;$('#close-explainer').textContent=current.view==='lesson'?'← Back to Lesson':current.view==='slides'?'← Back to Slides':current.view==='glossary'?'← Back to Glossary':'← Back to Learning';
 if(!dialog.open)dialog.showModal();dialog.scrollTop=0;decorate(dialog);
}
function breadcrumb(parts){const oid=current?.view==='lesson'?lessonById(current.id)?.objectiveId:current?.id;const objectiveNav=['objective','lesson'].includes(current?.view)?`<nav class="objective-nav" aria-label="Choose learning objective"><a href="#/home">All objectives</a>${course.objectives.map(o=>`<a href="#/objective/${o.id}" ${oid===o.id?'aria-current="page"':''} title="${e(o.title)}">Objective ${o.number}</a>`).join('')}</nav>`:'';return `${objectiveNav}<div class="breadcrumb"><a href="#/home">Overview</a>${parts.map(p=>`<span aria-hidden="true">/</span>${p.href?`<a href="${e(p.href)}">${e(p.label)}</a>`:`<span>${e(p.label)}</span>`}`).join('')}</div>`;}
function objectiveCard(o){const p=progress(course,state,o.id),count=course.questions.filter(q=>q.objectiveId===o.id).length;return `<article class="objective-card"><div class="card-top"><span class="objective-no">Objective ${String(o.number).padStart(2,'0')}</span>${pill(o.classLabel)}<span class="objective-symbol" aria-hidden="true">${['↗','Aa','2n','I·II','X','⇄','2ⁿ','∿'][o.number-1]}</span></div><h3>${e(o.title)}</h3><p>${e(o.goal)}</p>${p.done?`<progress value="${p.done}" max="${p.total}" aria-label="${p.done} of ${p.total} lessons complete"></progress>`:''}<div class="card-foot"><span>${p.total} ${p.total===1?'lesson':'lessons'} · ${count} ${count===1?'question':'questions'}</span><a href="#/objective/${o.id}">Explore objective <span aria-hidden="true">→</span></a></div></article>`;}
function home(){const p=progress(course,state),last=state.lastLesson&&lessonById(state.lastLesson.route.id),selected=course.objectives.filter(o=>filter==='all'||o.classId===filter);return `<section class="hub-intro"><div class="eyebrow"><span class="gold-dot"></span>YOUR PERSONAL LEARNING WORKSPACE</div><h1>Meiosis &amp; Sexual Life Cycles</h1><p>Two classes, organised around eight learning objectives. Read simply, explore the original diagrams and understand the why.</p><div class="hero-tags"><span>BIO 1107</span><span>2 PowerPoints</span><span>30 original slides</span></div></section><section class="research-overview"><div class="small-label">YOUR LEARNING FOCUS</div><h2>Follow the chromosomes. Understand the process.</h2><details class="landing-source-note"><summary>How the objectives were organised</summary><p>${e(course.objectiveNote)}</p></details></section><section class="hub-tools"><div><strong>Continue your learning</strong><p>${p.done} of ${p.total} lessons marked complete · ${p.percent}%</p><progress value="${p.done}" max="${p.total}" aria-label="Course progress"></progress></div><div class="hero-actions"><a class="button primary" href="#/lesson/${last?last.id:'lesson-01'}">${last?'Continue learning':'Start learning'} →</a><button class="button" data-guide>Quick guide</button></div></section><section class="objective-picker-panel"><div class="small-label">OBJECTIVE-BASED LEARNING</div><h2>Your learning path</h2><label for="objective-select">Choose a learning objective</label><select id="objective-select"><option value="">Select an objective…</option>${course.classes.map(c=>`<optgroup label="${e(c.title||c.id)}">${course.objectives.filter(o=>o.classId===c.id).map(o=>`<option value="${o.id}">Objective ${o.number}: ${e(o.title)}</option>`).join('')}</optgroup>`).join('')}</select><p class="source-note">Choose one to open its lessons, diagrams and questions. Objectives are inferred from your PowerPoint material.</p></section><section class="quick-glossary"><div><h2>Explain the why in seconds</h2><p>Tap an underlined term for its meaning, mechanism and memory aid. Return to the same reading position.</p></div><a class="button" href="#/glossary">Open simple glossary →</a></section>`;}

function objectiveView(id){const o=objectiveById(id);if(!o)return notFound();const lessons=course.lessons.filter(l=>l.objectiveId===id),q=course.questions.filter(q=>q.objectiveId===id),p=progress(course,state,id);return `${breadcrumb([{label:o.classLabel},{label:'Objective '+o.number}])}<div class="eyebrow">${e(o.classLabel)} · OBJECTIVE ${o.number}</div><h1 class="page-title">${e(o.title)}</h1><div class="objective-banner"><h2>What you will understand</h2><p>${e(o.goal)}</p><div class="source-note"><strong>Inferred learning objective.</strong> Derived from ${o.classLabel} slides ${o.sourceSlides.map(x=>Number(x.split('s').at(-1))).join(', ')}. ${p.done} of ${p.total} lessons marked complete.</div></div><div class="section-head"><h2>Lessons in this objective</h2><a class="text-link" href="#/home">All objectives</a></div><div class="lesson-list">${lessons.map(l=>`<article class="lesson-row"><img class="lesson-thumb" src="${e(l.figure.src)}" alt="" loading="lazy"><div><h3>${e(l.title)}</h3><p>Slide ${l.sourceNumber} · ${state.complete.includes(l.id)?'✓ Marked complete':'Ready to explore'}</p></div><a class="button soft" href="#/lesson/${l.id}">Open lesson →</a></article>`).join('')}</div>${q.length?`<div class="section-head"><h2>Check your understanding</h2><a class="button" href="#/practice/${id}">${q.length} original ${q.length===1?'question':'questions'} →</a></div>`:''}<div class="lesson-nav">${o.number>1?`<a class="button" href="#/objective/o${o.number-1}">← Previous objective</a>`:'<span></span>'}${o.number<8?`<a class="button" href="#/objective/o${o.number+1}">Next objective →</a>`:'<a class="button" href="#/practice/all">Review all questions →</a>'}</div>`;}
function quizCard(q){const choice=state.answers[q.id],attempted=Number.isInteger(choice),correct=choice===q.correct;return `<section class="quiz-card" id="question-${q.id}" aria-labelledby="prompt-${q.id}"><div class="question-label">ORIGINAL THOUGHT QUESTION · ${q.classId==='class1'?'CLASS 1':'CLASS 2'}, SLIDE ${q.sourceNumber}</div><h3 id="prompt-${q.id}">${e(q.prompt)}</h3><div class="options" role="group" aria-labelledby="prompt-${q.id}">${q.options.map((opt,i)=>`<button id="${q.id}-option-${i}" class="option ${attempted&&i===q.correct?'correct':''} ${choice===i?'selected '+(!correct?'incorrect':''):''}" data-answer="${q.id}" data-choice="${i}" aria-pressed="${choice===i}"><span class="letter" aria-hidden="true">${'ABCD'[i]}</span><span>${e(opt)}</span></button>`).join('')}</div>${attempted?`<div class="feedback ${correct?'':'wrong'}" role="status"><strong>${correct?'Correct.':'Not quite. Correct answer: '+ 'ABCD'[q.correct]+'.'}</strong>${mark(q.feedback)}<p class="source-note">Answer checked against the highlighted option in your PowerPoint.</p><button class="text-link" data-retry="${q.id}">Try this question again</button></div>`:''}</section>`;}
function lessonView(id){const l=lessonById(id);if(!l)return notFound();const o=objectiveById(l.objectiveId),i=course.lessons.indexOf(l),done=state.complete.includes(id),saved=state.bookmarks.includes(id),related=course.lessons.filter(x=>x.objectiveId===o.id),questions=course.questions.filter(q=>q.lessonId===id);return `${breadcrumb([{label:o.classLabel,href:'#/objective/'+o.id},{label:'Objective '+o.number,href:'#/objective/'+o.id},{label:'Lesson '+l.number}])}<div class="lesson-layout"><article class="lesson-content"><div class="eyebrow">OBJECTIVE ${o.number} · ${e(o.classLabel)}</div><h1>${e(l.title)}</h1><div class="lesson-meta"><span>Lesson ${l.number} of 16</span><span>Source: ${e(o.classLabel)}, slide ${l.sourceNumber}</span><span>Underlined terms are clickable</span></div><div class="reading-tools" aria-label="Reading tools"><button class="button small" data-reading-mode aria-pressed="${state.readingMode==='quick'}">${state.readingMode==='quick'?'Full lesson':'Quick revision'}</button><button class="button small" data-expand="true">Expand sections</button><button class="button small" data-expand="false">Collapse sections</button><button class="button small" data-lookup>Look up selected text</button><button class="button small" data-guide>Help</button><button class="button small" data-share>Copy lesson link</button></div>${state.readingMode==='quick'?`<div class="insight"><h3>QUICK REVISION</h3><p>${mark(l.memory)}</p></div><details class="source-details" id="full-${id}"><summary>Read the complete lesson</summary>`:''}<div class="lesson-body">${l.body.map(t=>`<p>${mark(t)}</p>`).join('')}</div>${state.readingMode==='quick'?'</details>':''}<figure class="lesson-figure"><button id="figure-${id}" class="figure-open" data-figure="${id}" aria-label="Explore the diagram: ${e(l.title)}"><img src="${e(l.figure.src)}" alt="${e(l.figure.alt)}" width="${l.figure.width}" height="${l.figure.height}"></button><figcaption><span>Original illustration from your PowerPoint</span><button class="text-link" data-figure="${id}">Explore diagram ↗</button></figcaption></figure><details class="source-details" id="diagram-explanation-${id}"><summary>Explain this diagram simply</summary><h3>What it shows</h3><p>${mark(l.figure.description)}</p><h3>Why it matters</h3><p>${mark(l.why)}</p><p>${e(l.figure.caution)}</p>${chips(l.figure.terms)}</details><div class="insight"><h3>IF YOU REMEMBER ONE THING</h3><p>${mark(l.memory)}</p></div><section class="why-section"><h2>Why does this matter?</h2><p>${mark(l.why)}</p>${chips(l.figure.terms)}</section>${questions.map(quizCard).join('')}<details class="source-details" id="original-${id}"><summary>Original slide wording & source</summary><p>Complete editable text extracted from ${e(course.classes.find(c=>c.id===l.classId).filename)}, slide ${l.sourceNumber}.</p><div class="source-text">${e(l.sourceText.join('\n\n'))}</div><a class="button small" href="#/slides/${l.classId}/${l.sourceNumber}">View full original slide ↗</a></details><details class="source-details" id="notes-${id}"><summary>My notes for this lesson</summary><label for="note-${id}" class="source-note">Write the idea in your own words. Notes stay in this browser.</label><textarea class="note-area" id="note-${id}" data-note="${id}" placeholder="What made this concept click?" maxlength="20000">${e(state.notes[id]||'')}</textarea><div class="save-status" id="note-status-${id}" role="status">${state.notes[id]?'Note saved locally.':'No note saved yet.'}</div></details><div class="lesson-nav">${i>0?`<a class="button" href="#/lesson/${course.lessons[i-1].id}">← Previous lesson</a>`:'<a class="button" href="#/home">← Overview</a>'}${i<15?`<a class="button primary" href="#/lesson/${course.lessons[i+1].id}">Next lesson →</a>`:'<a class="button primary" href="#/practice/all">Review the questions →</a>'}</div></article><aside class="lesson-rail" aria-label="Lesson tools"><div class="rail-block"><h2>YOUR PROGRESS</h2><button id="mark-complete" class="button ${done?'soft':'primary'}" data-complete="${id}" aria-pressed="${done}">${done?'✓ Completed':'Mark complete'}</button><button class="button" data-bookmark="${id}" aria-pressed="${saved}">${saved?'★ Bookmarked':'☆ Bookmark lesson'}</button><p class="local-note">Progress is saved in this browser.</p></div><div class="rail-block"><h2>IN THIS OBJECTIVE</h2>${related.map(x=>`<a href="#/lesson/${x.id}" ${x.id===id?'class="current" aria-current="page"':''}><span>${state.complete.includes(x.id)?'✓':'○'}</span><span>${e(x.title)}</span></a>`).join('')}<a href="#/objective/${o.id}">← Objective overview</a></div><div class="rail-block"><h2>LEARNING TOOLS</h2><a href="#/glossary">Simple glossary ↗</a><a href="#/practice/${o.id}">Thought questions ↗</a><a href="#/slides/${l.classId}/${l.sourceNumber}">Original slide ↗</a></div></aside></div>`;}
function glossaryView(){return `${breadcrumb([{label:'Glossary'}])}<div class="eyebrow">A CLEAR IDEA IN SECONDS</div><h1 class="page-title">The simple glossary</h1><p class="page-intro">The meaning, the mechanism and a way to remember it. Open a term to explore its related concepts.</p>${state.lastLesson?'<button class="button soft" data-last-lesson>← Back to Lesson</button>':''}<div class="glossary-tools"><label class="sr-only" for="glossary-search">Search glossary</label><input type="search" id="glossary-search" class="large-search" placeholder="Try locus, diploid or crossing over…" value="${e(glossaryQuery)}"><button class="button" id="glossary-clear">Clear</button></div><details class="source-details"><summary>Browse alphabetically</summary><div class="alphabet" aria-label="Filter glossary by initial">${['All',...new Set(terms.map(t=>t.term[0].toUpperCase()).sort())].map(l=>`<button data-letter="${e(l)}" aria-pressed="${glossaryLetter===l}">${e(l)}</button>`).join('')}</div></details><p class="source-note" id="glossary-count" aria-live="polite"></p><div id="glossary-results"></div><details class="source-details"><summary>Explore all the diagrams</summary><div class="term-chips">${course.lessons.map(l=>`<button data-figure="${l.id}">${String(l.number).padStart(2,'0')} · ${e(l.title)}</button>`).join('')}</div></details>`;}
function fillGlossary(){if(!$('#glossary-results'))return;const q=glossaryQuery.toLowerCase().trim();const shown=terms.filter(t=>(glossaryLetter==='All'||t.term[0].toUpperCase()===glossaryLetter)&&[t.term,...t.aliases,t.simple].join(' ').toLowerCase().includes(q)).sort((a,b)=>a.term.localeCompare(b.term));$('#glossary-count').textContent=`${shown.length} of ${terms.length} terms`;$('#glossary-results').innerHTML=shown.length?`<div class="glossary-grid">${shown.map(t=>`<button class="term-card" data-term="${t.id}"><h2>${e(t.term)} ↗</h2></button>`).join('')}</div>`:'<div class="empty"><h2>No matching terms</h2><p>Try a shorter term or choose All.</p></div>';}
function practiceView(id){let selected=course.questions;if(id&&id!=='all'){if(id==='class1'||id==='class2')selected=selected.filter(q=>q.classId===id);else selected=selected.filter(q=>q.objectiveId===id);}const result=quizResult(selected,state.answers);return `${breadcrumb([{label:'Thought questions'}])}<div class="eyebrow">PRACTISE WITH THE ORIGINAL QUESTIONS</div><h1 class="page-title">Check your understanding</h1><p class="page-intro">All 10 questions come from your PowerPoints. Choose an answer to see a short explanation. You can retry any question.</p><div class="filter-row">${[['all','All 10'],['class1','Class 1'],['class2','Class 2']].map(([v,t])=>`<a class="button small ${id===v?'soft':''}" href="#/practice/${v}">${t}</a>`).join('')}</div><div class="objective-banner"><strong>${result.correct} correct · ${result.attempted} attempted · ${result.total} questions in this view</strong><p>Your most recent answer is saved. Lesson completion is marked separately.</p></div>${selected.map(quizCard).join('')||'<div class="empty">No questions in this selection. <a href="#/practice/all">View all questions</a>.</div>'}<button class="button" data-reset-answers="${e(id||'all')}">Reset answers in this view</button>`;}
function slidesView(classId,page){const deck=decks.find(d=>d.id===classId);if(!deck)return notFound();const number=Number(page||1);const s=deck.slides.find(s=>s.number===number);if(!s)return notFound();const lesson=course.lessons.find(l=>l.sourceId===s.id);return `${breadcrumb([{label:'Original slides'}])}<div class="eyebrow">THE COMPLETE SOURCE MATERIAL</div><h1 class="page-title">Original slides</h1><p class="page-intro">Both PowerPoints, in their original sequence. Title slides, questions, illustrations and complete text are all retained.</p><div class="slides-toolbar">${decks.map(d=>`<a class="button ${d.id===classId?'soft':''}" href="#/slides/${d.id}/1">${d.title} · ${d.slides.length} slides</a>`).join('')}<a class="button" href="${deck.download}" download>Download ${deck.title} PPTX ↓</a><label for="slide-select" class="sr-only">Choose slide</label><select id="slide-select" data-class="${classId}">${deck.slides.map(x=>`<option value="${x.number}" ${number===x.number?'selected':''}>Slide ${x.number}</option>`).join('')}</select></div><div class="source-slide-label"><h2>${e(deck.title)} · Slide ${number} of ${deck.slides.length}</h2>${lesson?`<a class="button small" href="#/lesson/${lesson.id}">Open guided lesson →</a>`:''}</div>${state.lastLesson?'<button class="button small" data-last-lesson>← Back to Lesson</button>':''}<div class="slide-viewer"><button class="figure-open" data-slide="${s.id}" aria-label="Enlarge original slide ${number}"><img src="${e(s.preview)}" alt="${e(s.title)}" width="1440" height="810"></button></div><div class="lesson-nav">${number>1?`<a class="button" href="#/slides/${classId}/${number-1}">← Previous slide</a>`:'<span></span>'}${number<deck.slides.length?`<a class="button primary" href="#/slides/${classId}/${number+1}">Next slide →</a>`:'<a class="button" href="#/home">Overview →</a>'}</div><details class="source-details" id="slide-text-${s.id}"><summary>Read complete slide text</summary><div class="source-text">${e(s.text.join('\n\n'))}</div>${s.notes.length?`<h3>Speaker notes</h3><div class="source-text">${e(s.notes.join('\n'))}</div>`:''}</details><details class="source-details"><summary>Browse slide thumbnails</summary><div class="slide-strip" aria-label="Slides in original order">${deck.slides.map(x=>`<a href="#/slides/${classId}/${x.number}" ${number===x.number?'class="current" aria-current="page"':''}><img src="${e(x.preview)}" alt="" loading="lazy"><span>Slide ${x.number}</span></a>`).join('')}</div></details>`;}
function notesView(){const ids=[...new Set([...state.bookmarks,...Object.keys(state.notes).filter(k=>state.notes[k].trim())])].filter(id=>lessonById(id));return `${breadcrumb([{label:'My notes & bookmarks'}])}<div class="eyebrow">YOUR OWN WORDS</div><h1 class="page-title">My notes & bookmarks</h1><p class="page-intro">Saved in this browser only. Download your notes to keep a separate copy.</p><div class="hero-actions"><button class="button primary" id="download-notes">Download notes ↓</button><a class="button" href="#/home">Browse lessons</a></div><div class="notes-grid">${ids.map(id=>{const l=lessonById(id);return `<article class="note-card"><div class="small-label">${state.bookmarks.includes(id)?'★ BOOKMARKED':'LESSON NOTE'}</div><h2>${e(l.title)}</h2><pre>${e(state.notes[id]||'No note yet. Open the lesson to add one.')}</pre><a class="button small" href="#/lesson/${id}">Return to lesson →</a></article>`}).join('')||'<div class="empty"><h2>Your space is ready</h2><p>Bookmark a lesson or open My notes within a lesson to add your first note.</p></div>'}</div>`;}
function searchView(q){const found=searchContent(q,course,terms),total=found.lessons.length+found.terms.length+found.objectives.length;return `${breadcrumb([{label:'Search'}])}<div class="eyebrow">FIND THE IDEA YOU NEED</div><h1 class="page-title">Search the Learning Hub</h1><form id="page-search-form" class="glossary-tools"><label class="sr-only" for="page-search">Search query</label><input class="large-search" id="page-search" type="search" value="${e(q)}" placeholder="Try chromosome, meiosis II or mutation"><button class="button primary">Search</button></form><p class="source-note">${q?`${total} results for “${e(q)}”`:'Search across lessons, objectives and glossary terms.'}</p>${found.objectives.length?`<section class="search-section"><h2>Objectives</h2>${found.objectives.map(o=>`<a class="search-item" href="#/objective/${o.id}"><strong>${e(o.title)}</strong><span>${e(o.goal)}</span></a>`).join('')}</section>`:''}${found.lessons.length?`<section class="search-section"><h2>Lessons</h2>${found.lessons.map(l=>`<a class="search-item" href="#/lesson/${l.id}"><strong>${e(l.title)}</strong><span>${e(l.takeaway)}</span></a>`).join('')}</section>`:''}${found.terms.length?`<section class="search-section"><h2>Glossary</h2><div class="glossary-grid">${found.terms.map(t=>`<button class="term-card" data-term="${t.id}"><h2>${e(t.term)} ↗</h2><p>${e(t.simple)}</p></button>`).join('')}</div></section>`:''}${q&&!total?'<div class="empty">No matching concepts. Try a shorter or different term.</div>':''}`;}
function guideView(){return `${breadcrumb([{label:'User Guide'}])}<div class="eyebrow">GET STARTED IN SECONDS</div><h1 class="page-title">User Guide</h1><p class="page-intro">Choose an objective. Understand the idea. Explore the why.</p>${state.lastLesson?'<button class="button soft" data-last-lesson>← Back to Lesson</button>':''}<section class="about-section"><h2>1. Choose your learning objective</h2><p>On the landing page, select an objective from the dropdown. In the left panel, expand Class 1 or Class 2 to find its objectives. Each objective opens the relevant lessons and questions.</p></section><section class="about-section"><h2>2. Control the left panel</h2><p>Use ☰ in the top bar to collapse or expand the desktop panel. Your choice is remembered. On a phone, ☰ opens the navigation menu.</p></section><section class="about-section"><h2>3. Read at your own pace</h2><p>Full lesson shows the teaching explanation. Quick revision puts the main idea first and keeps the complete lesson available under Read the complete lesson. Use Expand sections or Collapse sections as needed.</p></section><section class="about-section"><h2>4. Understand a term or diagram</h2><p>Tap an underlined word for its simple meaning, how it works and a memory aid. Related terms help you explore; Previous term retraces your glossary trail.</p><p>Select a short word or phrase in the lesson, then choose Look up selected text. An exact match opens its explanation; otherwise the glossary searches for your selection.</p><p>Choose Explain this diagram simply for an inline explanation, or Explore diagram for a larger view and clickable labels. Back to diagram returns from a label explanation.</p><p>Use Back to Lesson to restore your place. Escape and browser Back also close explanations.</p></section><section class="about-section"><h2>5. Practise and keep your progress</h2><p>Try the original thought questions to see feedback. You can retry any answer. Mark complete records lesson completion separately from quiz scores. Bookmark lessons and write your own notes.</p></section><section class="about-section"><h2>6. Search and change appearance</h2><p>Search the top bar for lessons, objectives or terms. Press / to focus search. Choose Light, Dark or Colour from the appearance menu. Aa changes lesson text size.</p></section><section class="about-section"><h2>7. Save and share</h2><p>Your notes and progress stay in the current browser and website address. Under My notes, export a backup before changing devices or clearing browser data. Importing a backup replaces the saved data after confirmation.</p><p>Copy lesson link shares the lesson address only. Your notes and answers are not included. Site access protection still applies.</p></section><section class="about-section"><h2>8. Check the original material</h2><p>Original slides preserves all 30 slides from both PowerPoints. Every lesson identifies its source slide. Course & sources explains inferred objectives and supplementary glossary notes.</p><a class="button" href="#/about">Course & sources →</a></section>`;}
function developerView(){return `${breadcrumb([{label:'About the Developer'}])}<div class="eyebrow">THE PERSON BEHIND THE HUB</div><h1 class="page-title">About the Developer</h1>${state.lastLesson?'<button class="button soft" data-last-lesson>← Back to Lesson</button>':''}<article class="developer-profile"><div><h2>Progress Ajayi</h2><p class="developer-role">Physiologist &amp; Bioinformatician</p><p>Progress Ajayi develops research and learning tools that make complex scientific information easier to understand and use.</p><p>This Meiosis Learning Hub adapts the design and learning approach of his Appendicitis Research &amp; Statistical Learning Hub to the supplied biology PowerPoints.</p><details class="source-details"><summary>The learning approach</summary><p>Explain the why in seconds: clear meanings, simple mechanisms and memorable explanations, with the original learning material close at hand.</p></details><details class="source-details"><summary>Course content</summary><p>Biology teaching material: BIO 1107, Principles of Biology 1. Instructor: Mrs. Oyawale. The original presentations are credited separately from app development.</p></details><nav class="developer-links" aria-label="Connect with Progress Ajayi"><a class="button" href="https://www.linkedin.com/in/progress-ajayi" target="_blank" rel="noopener noreferrer">LinkedIn ↗</a><a class="button" href="https://github.com/ajayiprogress04-ctrl" target="_blank" rel="noopener noreferrer">GitHub ↗</a><a class="button" href="mailto:ajayiprogress04@gmail.com">Email</a></nav></div></article>`;}
function aboutView(){return `${breadcrumb([{label:'Guide & sources'}])}<div class="eyebrow">YOUR COURSE COMPANION</div><h1 class="page-title">Guide & sources</h1><section class="about-section"><h2>A simple way to learn</h2><ol><li>Choose an objective, then open a lesson.</li><li>Tap an underlined term or explore a diagram when you need the simple idea.</li><li>Use Back to Lesson to close the explanation without losing your place.</li><li>Answer the original thought questions, add notes and mark lessons complete.</li></ol><p>Use the header’s appearance control for Light, Dark or Colour mode. Press / to focus search. Escape closes a term or diagram. The browser Back button also closes explanations.</p></section><section class="about-section"><h2>The two source documents</h2><p>Biology Lab 1107: Meiosis and sexual life cycle. BIO 1107, Principles of Biology 1. Instructor: Mrs. Oyawale.</p><ul>${course.classes.map(c=>`<li><a href="${c.download}" download>${e(c.filename)}</a> · ${c.slideCount} slides</li>`).join('')}</ul><p>${e(course.objectiveNote)}</p><p>All 30 source slides are preserved. The guided path groups the 16 teaching slides into eight objectives and includes all 10 thought questions. Repeated headings are consolidated for readability; complete source text remains available.</p></section><section class="about-section"><h2>Diagrams and short explanations</h2><p>The original illustrations remain unchanged apart from web image optimisation. They use symbolic chromosomes. The diagram explanations identify important qualifications, including the general four-cell model and possible gamete combinations across different meiotic events.</p><p>The crossing-over illustration places a chiasma marker near centromere-like circles. A chiasma is distinct from a centromere. Use the exchanged colour segments to understand the main idea.</p><p>The glossary adds short teaching explanations. Genetics terminology was cross-checked with <a href="https://www.genome.gov/genetics-glossary" target="_blank" rel="noopener noreferrer">NHGRI’s Talking Glossary of Genetic Terms</a>, including <a href="https://www.genome.gov/genetics-glossary/Allele" target="_blank" rel="noopener noreferrer">allele</a>, <a href="https://www.genome.gov/genetics-glossary/Nucleolus" target="_blank" rel="noopener noreferrer">nucleolus</a> and <a href="https://www.genome.gov/genetics-glossary/Centriole" target="_blank" rel="noopener noreferrer">centriole</a>. These references support glossary clarification; the PowerPoints remain the source of the lessons.</p></section><section class="about-section"><h2>Your saved work</h2><p>Notes, answers, bookmarks, progress and appearance stay in this browser. No account, AI service, API key or paid service is needed. Private browsing or clearing site data can remove saved work. This app does not sync across devices.</p><button class="button" id="download-backup">Export my learning backup ↓</button> <label class="button" for="import-backup">Import backup ↑</label><input class="sr-only" id="import-backup" type="file" accept="application/json,.json"><p class="source-note">Import replaces local progress and notes after confirmation.</p><button class="text-link" id="reset-progress">Reset all local learning data</button></section>`;}
function notFound(){return '<section class="empty"><h1>That page is not available</h1><p>The lesson or slide link may be incomplete.</p><a class="button primary" href="#/home">Return to learning overview</a></section>';}
function compactSections(html){return html.replace(/<section class="about-section"><h2>([\s\S]*?)<\/h2>([\s\S]*?)<\/section>/g,(_,title,body)=>`<details class="source-details help-disclosure"><summary>${title}</summary>${body}</details>`);}
function renderView(r){switch(r.view){case'home':return home();case'objective':return objectiveView(r.id);case'lesson':return lessonView(r.id);case'glossary':return glossaryView();case'practice':return practiceView(r.id);case'slides':return slidesView(r.id,r.page);case'notes':return notesView();case'search':return searchView(r.q);case'about':return compactSections(aboutView());case'guide':return compactSections(guideView());case'developer':return developerView();default:return notFound();}}
function decorate(root=main){root.querySelectorAll('[data-term]:not([id])').forEach((el,i)=>el.id=`${root===main?'main':'modal'}-term-${i}`);root.querySelectorAll('img').forEach(img=>{img.addEventListener('error',()=>{if(img.dataset.failed)return;img.dataset.failed='true';img.hidden=true;const error=document.createElement('p');error.className='image-error';error.textContent='This image could not load. The complete text remains available in Original Slides. Check your connection or project assets.';img.parentElement.append(error);});});if(current?.view==='glossary'&&root===main){fillGlossary();}}
function refreshKeepingContext(){const context=capture();main.innerHTML=renderView(current);decorate();updateShell();restore(context);}
function download(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('pointerdown',ev=>{if(ev.target.closest?.('[data-lookup]'))ev.preventDefault();});
function lookupSelection(){const query=String(window.getSelection?.()||'').trim().slice(0,100);if(!query){toast('Select a word in the lesson first, then choose Look up selected text.');return;}const found=terms.find(t=>[t.term,...t.aliases].some(a=>a.toLowerCase()===query.toLowerCase()));if(found)openOverlay('term',found.id);else{glossaryQuery=query;glossaryLetter='All';navigate({view:'glossary'});}}
async function copyLessonLink(){const publicBase=document.querySelector('link[rel="canonical"]')?.href||location.origin+location.pathname;const link=publicBase+routeHash({...current,q:'',overlay:''});try{await navigator.clipboard.writeText(link);toast('Lesson link copied.');}catch{openOverlay('guide','start');const field=document.createElement('input');field.type='text';field.value=link;field.setAttribute('aria-label','Lesson link to copy');$('#explain-body').append(field);field.focus();field.select();}}
document.addEventListener('click',ev=>{
 const target=ev.target.closest('button,a');if(!target||!course)return;
 if(target.matches('[data-previous-term]')){const id=termTrail.pop();if(id){history.replaceState({overlay:true},'',routeHash({...current,overlay:'term:'+id}));renderOverlay('term',id);}}
 else if(target.matches('[data-preview-zoom]')){previewZoom=target.dataset.previewZoom==='fit'?100:Math.max(50,Math.min(250,previewZoom+(target.dataset.previewZoom==='in'?25:-25)));$('#preview-page')?.setAttribute('style','width:'+previewZoom+'%;max-width:none');if($('#preview-zoom-status'))$('#preview-zoom-status').textContent=previewZoom+'%';}
 else if(target.matches('[data-preview-fullscreen]')){if(dialog.requestFullscreen)dialog.requestFullscreen().catch(()=>toast('Full screen is unavailable in this browser.'));else toast('Use your browser’s full screen control.');}
 else if(target.matches('[data-reading-mode]')){state.readingMode=state.readingMode==='quick'?'full':'quick';persist();refreshKeepingContext();}
 else if(target.matches('[data-expand]')){main.querySelectorAll('details').forEach(el=>el.open=target.dataset.expand==='true');capture();}
 else if(target.matches('[data-guide]'))openOverlay('guide','start');
 else if(target.matches('[data-lookup]'))lookupSelection();
 else if(target.matches('[data-share]'))copyLessonLink();
 else if(target.matches('[data-term]')){ev.preventDefault();openOverlay('term',target.dataset.term);}
 else if(target.matches('[data-figure]'))openOverlay('figure',target.dataset.figure);
 else if(target.matches('[data-slide]'))openOverlay('slide',target.dataset.slide);
 else if(target.matches('[data-return-figure]'))openOverlay('figure',target.dataset.returnFigure);
 else if(target.matches('a[href^="#/"]')){ev.preventDefault();navigate(parseRoute(target.getAttribute('href')));}
 else if(target.matches('[data-class-filter]')){filter=target.dataset.classFilter;refreshKeepingContext();}
 else if(target.matches('[data-last-lesson]')){if(state.lastLesson)navigate(state.lastLesson.route,{restoreContext:state.lastLesson});}
 else if(target.matches('[data-complete]')){state.complete=toggleValue(state.complete,target.dataset.complete);persist();refreshKeepingContext();toast(state.complete.includes(target.dataset.complete)?'Lesson marked complete.':'Completion mark removed.');}
 else if(target.matches('[data-bookmark]')){state.bookmarks=toggleValue(state.bookmarks,target.dataset.bookmark);persist();refreshKeepingContext();}
 else if(target.matches('[data-answer]')){state.answers[target.dataset.answer]=Number(target.dataset.choice);persist();refreshKeepingContext();document.getElementById(target.id)?.focus({preventScroll:true});}
 else if(target.matches('[data-retry]')){delete state.answers[target.dataset.retry];persist();refreshKeepingContext();}
 else if(target.matches('[data-reset-answers]')){let qs=course.questions;const id=target.dataset.resetAnswers;if(id!=='all')qs=qs.filter(q=>q.classId===id||q.objectiveId===id);if(confirm('Reset your answers in this view?')){for(const q of qs)delete state.answers[q.id];persist();refreshKeepingContext();}}
 else if(target.matches('[data-letter]')){glossaryLetter=target.dataset.letter;document.querySelectorAll('[data-letter]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.letter===glossaryLetter));fillGlossary();}
 else if(target.id==='glossary-clear'){glossaryQuery='';glossaryLetter='All';refreshKeepingContext();$('#glossary-search')?.focus();}
 else if(target.id==='download-notes'){const txt=course.lessons.filter(l=>state.notes[l.id]?.trim()).map(l=>l.title+'\n'+state.notes[l.id]).join('\n\n----------\n\n');download('Meiosis_My_Notes.txt',txt||'No notes saved yet.');}
 else if(target.id==='download-backup')download('Meiosis_Learning_Backup.json',JSON.stringify(state,null,2),'application/json');
 else if(target.id==='reset-progress'&&confirm('Delete this browser’s saved notes, answers, bookmarks and progress? Export a backup first if needed.')){state=storage.reset();applySettings();refreshKeepingContext();toast('Local learning data reset.');}
});
document.addEventListener('input',ev=>{const el=ev.target;if(el.id==='glossary-search'){glossaryQuery=el.value;fillGlossary();}if(el.matches('[data-note]')){state.notes[el.dataset.note]=el.value;const ok=persist();$('#note-status-'+el.dataset.note).textContent=ok?'Saved locally.':'Stored in this tab only. Export a backup before closing.';}});
document.addEventListener('change',async ev=>{const el=ev.target;if(el.id==='objective-select'&&objectiveById(el.value))navigate({view:'objective',id:el.value});if(el.id==='slide-select')navigate({view:'slides',id:el.dataset.class,page:el.value});if(el.id==='import-backup'){const f=el.files[0];if(!f)return;try{if(f.size>2000000)throw Error('The backup is too large.');const data=JSON.parse(await f.text());if(data.version!==1||!Array.isArray(data.complete)||typeof data.notes!=='object')throw Error('This is not a supported learning backup.');if(confirm('Replace your saved learning data with this backup?')){state={...storage.reset(),...data,contexts:{},lastLesson:null};persist();state=storage.load();applySettings();refreshKeepingContext();toast('Learning backup imported.');}}catch(err){toast('Could not import backup: '+err.message);}el.value='';}});
$('#search-form').addEventListener('submit',ev=>{ev.preventDefault();navigate({view:'search',q:$('#global-search').value.trim()});});
document.addEventListener('submit',ev=>{if(ev.target.id==='page-search-form'){ev.preventDefault();navigate({view:'search',q:$('#page-search').value.trim()});}});
$('#theme').addEventListener('change',ev=>{state.theme=ev.target.value;applySettings();persist();});
$('#text-size').addEventListener('click',()=>{state.fontSize=state.fontSize==='large'?'normal':'large';applySettings();persist();});
$('#global-back').addEventListener('click',goBack);$('#close-explainer').addEventListener('click',closeOverlay);$('#close-x').addEventListener('click',closeOverlay);
dialog.addEventListener('cancel',ev=>{ev.preventDefault();closeOverlay();});
dialog.addEventListener('click',ev=>{if(ev.target===dialog){const r=dialog.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)closeOverlay();}});
const desktopNavigation=()=>window.matchMedia?.('(min-width: 801px)').matches===true;
function updateMenuButton(){const desktop=desktopNavigation(),expanded=desktop?!state.sidebarCollapsed:$('#mobile-menu').open;$('#menu-toggle').setAttribute('aria-expanded',String(expanded));$('#menu-toggle').setAttribute('aria-controls',desktop?'learning-sidebar':'mobile-menu');$('#menu-toggle').setAttribute('aria-label',expanded?'Collapse navigation':'Expand navigation');}
$('#menu-toggle').addEventListener('click',()=>{if(desktopNavigation()){state.sidebarCollapsed=!state.sidebarCollapsed;applySettings();persist();}else{$('#mobile-menu').showModal();}updateMenuButton();});$('#menu-close').addEventListener('click',()=>{$('#mobile-menu').close();updateMenuButton();});$('#mobile-menu').addEventListener('close',updateMenuButton);window.addEventListener('resize',updateMenuButton);
document.addEventListener('keydown',ev=>{if(ev.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)&&!dialog.open){ev.preventDefault();$('#global-search').focus();}});
window.addEventListener('popstate',()=>{if(course)syncRoute();});window.addEventListener('hashchange',()=>{if(course)syncRoute();});window.addEventListener('pagehide',capture);
async function boot(){applySettings();updateMenuButton();try{const urls=['content/course.json','content/glossary.json','content/source-slides.json'];const data=await Promise.all(urls.map(async url=>{const r=await fetch(url);if(!r.ok)throw Error('Could not load '+url+' ('+r.status+').');return r.json();}));[course,terms,decks]=data;assertContent(course,terms,decks);syncRoute();}catch(err){main.innerHTML=`<div class="empty"><h1>The learning content could not load</h1><p>${e(err.message)}</p><p>Run the project through its local server instead of opening index.html directly. See the included README.</p><button class="button primary" id="reload-content">Try again</button><p><a href="sources/class1.pptx">Download Class 1</a> · <a href="sources/class2.pptx">Download Class 2</a></p></div>`;$('#reload-content').addEventListener('click',()=>location.reload());}}
boot();
